    print(f"Total RERA questions: {len(RERA_QUESTIONS)}")
    from collections import Counter
    tiers = Counter(q["tier"] for q in RERA_QUESTIONS)
    for t in sorted(tiers):
        print(f"  Tier {t}: {tiers[t]} questions")
